DO BEGIN
  CREATE TABLE m (id Uint64 NOT NULL, PRIMARY KEY (id));
  SELECT * FROM AS_TABLE([<|id: 1|>]);
END DO;
DO BEGIN SELECT 1; CREATE TABLE n (id Uint64 NOT NULL, PRIMARY KEY (id)); END DO;
DO BEGIN SELECT * FROM m JOIN n ON m.id = n.id; DROP TABLE n; END DO;
DEFINE ACTION $w() AS UPSERT INTO m (id) VALUES (1); END DEFINE;
DEFINE ACTION $s() AS DROP TABLE m; END DEFINE;
DO $w();
DO $s();
DO $missing();
EVALUATE FOR $i IN AsList(1) DO BEGIN BATCH UPDATE m SET id = 2; DROP TABLE m; END DO;
DO BEGIN UPSERT OBJECT o (TYPE SECRET) WITH value = 'x'; SELECT 1; END DO;
